package org.sleepwell.app;
final class PictureProof {final String run,nonce,key;final int unit;final long issued;private boolean consumed;PictureProof(String run,int unit,String nonce,String key,long issued){if(run==null||run.isBlank()||unit<0||nonce==null||nonce.isBlank()||key==null||!key.matches("[0-9a-f]{64}")||issued<0)throw new IllegalArgumentException("Invalid picture request");this.run=run;this.unit=unit;this.nonce=nonce;this.key=key;this.issued=issued;}boolean consume(String responseRun,int responseUnit,String responseNonce,String responseKey,long at,long now,String currentRun,int currentUnit,String currentKey,boolean live,boolean fallback){if(consumed)return false;if(!live||!run.equals(currentRun)||unit!=currentUnit||!key.equals(currentKey)){consumed=true;return false;}if(!run.equals(responseRun)||unit!=responseUnit||!nonce.equals(responseNonce)||!key.equals(responseKey)||!fallback&&(at<issued||at>now||now-at>10000))return false;consumed=true;return true;}}
